
$(function() {
    $('#sdate').datepicker({
        dateFormat: 'dd/mm/yy',
        maxDate:'0',
        onSelect: function() {
            $(this).change();
            makeFormEmpty();
            $('.find-and-load').submit();
        }
    });
});




$(function() {
    $(document).on("keyup", "input[type=number].outstanding-input", function (e) {
        calculateOutstanding($(this).closest('table'));
    });
});

function makeFormEmpty(){
    $('#form-container').html('');
}


function calculateOutstanding(obj){
    var appordep,
        inamount = evaluated_value = evaluated_debit = evaluated_credit = 0,
        tr = obj.closest('tr'),
        table = obj.closest('table'),
        value = parseFloat(tr.find('.value').val()),
        inpercent = parseFloat(tr.find('.inpercent').val()),
        debit = removeNumberFormat(tr.find('.debit').text()),
        credit = removeNumberFormat(tr.find('.credit').text());

    tr.find('.inamount').val('0.00');
    tr.find('.evaluated-debit').html(bdt_format(debit,2));
    tr.find('.evaluated-credit').html(bdt_format(credit,2));

    appordep = tr.find('.appordep').val();
    if(appordep == '0'){
        tr.find('.inpercent').val('0.00');
    } else{
        inamount = (value * inpercent)/100;
        if(appordep == 'APPRICIATION') {
            evaluated_value = value + inamount;
        } else {
            evaluated_value = value - inamount;
        }

        if(inamount > 0){
            evaluated_debit = Math.abs(evaluated_value);
        } else if(inamount < 0) {
            evaluated_credit = Math.abs(evaluated_value);
        }
        inamount = Math.abs(inamount);
        tr.find('.inamount').val(inamount.toFixed(2));
        tr.find('.evaluated-debit').html(bdt_format(evaluated_debit,2));
        tr.find('.evaluated-credit').html(bdt_format(evaluated_credit,2));
    }
    calculateTotalEvaluation(table);
}


function calculateEvaluationByFigure(obj){
    var appordep,
        inpercent = evaluated_value = evaluated_debit = evaluated_credit = 0,
        tr = obj.closest('tr'),
        table = obj.closest('table'),
        value = parseFloat(tr.find('.value').val()),
        inamount = parseFloat(tr.find('.inamount').val()),
        debit = removeNumberFormat(tr.find('.debit').text()),
        credit = removeNumberFormat(tr.find('.credit').text());

    tr.find('.inpercent').val('0.00');
    tr.find('.evaluated-debit').html(bdt_format(debit,2));
    tr.find('.evaluated-credit').html(bdt_format(credit,2));
    appordep = tr.find('.appordep').val();

    if(appordep != '0'){
        tr.find('.inamount').val('0.00');
    }else{
        inpercent = (100 * inamount)/value;
        if(appordep == 'APPRICIATION') {
            evaluated_value = value + inamount;
        } else {
            evaluated_value = value - inamount;
        }

        if(evaluated_value > 0){
            evaluated_debit = Math.abs(evaluated_value);
        } else if(evaluated_value < 0) {
            evaluated_credit = Math.abs(evaluated_value);
        }
        inpercent = Math.abs(inpercent);
        tr.find('.inpercent').val(inpercent.toFixed(3));

        tr.find('.evaluated-debit').html(bdt_format(evaluated_debit,2));
        tr.find('.evaluated-credit').html(bdt_format(evaluated_credit,2));
    }
    calculateTotalEvaluation(table);
}


function calculateOutstanding(table)
{
    var tr, debit = credit = 0;
    table.find( 'tbody tr' ).each(function() {
        tr = $(this);
        //alert(tr.find('.outstanding-debit').val())
        debit += parseFloat(tr.find('.outstanding-debit').val());
        credit += parseFloat(tr.find('.outstanding-credit').val());
    });

    $( '.total-outstanding-debit').html(bdt_format(debit,2));
    $( '.total-outstanding-credit').html(bdt_format(credit,2));
}

